// Helper: Firestore functions mapped from compat SDK
const collection = (db, name) => db.collection(name);
const getDocs = (ref) => ref.get();
const getDoc = (ref) => ref.get();
const addDoc = (ref, data) => ref.add(data);
const setDoc = (ref, data, opts) => ref.set(data, opts || {});
const updateDoc = (ref, data) => ref.update(data);
const deleteDoc = (ref) => ref.delete();
const doc = (db, col, id) => id ? db.collection(col).doc(id) : db.collection(col).doc();
const query = (ref, ...constraints) => {
    let q = ref;
    constraints.forEach(c => { if (c) q = c(q); });
    return q;
};
const where = (field, op, val) => (q) => q.where(field, op, val);
const orderBy = (field, dir) => (q) => q.orderBy(field, dir || 'asc');
const limit = (n) => (q) => q.limit(n);
const writeBatch = (db) => db.batch();
const onSnapshot = (ref, onNext, onError) => {
    if (ref && typeof ref.onSnapshot === 'function') {
        return ref.onSnapshot({includeMetadataChanges:true}, onNext, onError);
    }
    return () => {};
};

