/**
 * Fire confetti celebration effect
 */
const fireConfetti = () => {
    const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444'];
    // ✅ FIX: ลดจำนวน confetti บนมือถือ จาก 30 เป็น 10
    const isMobile = window.matchMedia('(hover: none) and (pointer: coarse)').matches;
    const count = isMobile ? 10 : 30;
    for(let i=0; i<count; i++) {
        const el = document.createElement('div');
        el.style.position = 'fixed';
        el.style.left = '50%';
        el.style.top = '50%';
        el.style.width = '8px';
        el.style.height = '8px';
        el.style.backgroundColor = colors[Math.floor(Math.random()*colors.length)];
        el.style.borderRadius = '50%';
        el.style.zIndex = '9999';
        el.style.pointerEvents = 'none';
        document.body.appendChild(el);
        
        const angle = Math.random() * Math.PI * 2;
        const velocity = 5 + Math.random() * 10;
        const tx = Math.cos(angle) * 100 * Math.random();
        const ty = Math.sin(angle) * 100 * Math.random();
        
        el.animate([
            { transform: 'translate(0,0) scale(1)', opacity: 1 },
            { transform: `translate(${tx}px, ${ty}px) scale(0)`, opacity: 0 }
        ], { duration: 800, easing: 'cubic-bezier(0, .9, .57, 1)' }).onfinish = () => el.remove();
    }
};

