    /**
     * Lock input field
     * @param {boolean} isLocked - Lock state
     * @param {string} msg - Message to display
     * @param {string} color - Color theme
     */
    lockInput(isLocked, msg, color) {
        const inp = document.getElementById('inp-new-loc');
        const feedback = document.getElementById('m-feedback-box');
        inp.disabled = isLocked;
        inp.parentElement.classList.toggle('opacity-50', isLocked);
        
        if(msg) {
            feedback.classList.remove('hidden');
            const colors = {
                emerald: 'bg-emerald-50 text-emerald-700 border border-emerald-100',
                brand: 'bg-brand-50 text-brand-700 border border-brand-100',
                written: 'bg-written-50 text-written-700 border border-written-100',
                orange: 'bg-orange-50 text-orange-700 border border-orange-100',
                amber: 'bg-amber-50 text-amber-700 border border-amber-100',
                red: 'bg-red-50 text-red-700 border border-red-100',
                reject: 'bg-reject-50 text-reject-700 border border-reject-100'
            };
            feedback.className = `p-4 rounded-xl text-base font-bold text-center shadow-sm ${colors[color]}`;
            feedback.textContent = msg;
        }
    },

    /**
     * Unlock edit mode
     * @param {boolean} isReset - Is reset mode
     */
    unlockEdit(isReset = false) {
        const inp = document.getElementById('inp-new-loc');
        const feedback = document.getElementById('m-feedback-box');
        const footer = document.getElementById('modal-footer');
        const userArea = document.getElementById('mode-normal');
        const btnEdit = document.getElementById('btn-user-edit');
        inp.disabled = false;
        inp.parentElement.classList.remove('opacity-50');
        if(!isReset) inp.focus();
        feedback.classList.add('hidden');
        footer.classList.remove('hidden');
        userArea.classList.remove('hidden');
        btnEdit.classList.add('hidden');
    },

