                (on ? 'border-2 border-blue-500 bg-blue-50' : 'border border-slate-200 bg-white') + '">'+
                '<div class="text-sm font-bold '+(on?'text-blue-700':'text-slate-700')+'">'+s.label+'</div>'+
                '<div class="text-[11px] text-slate-400">'+s.sub+'</div></button>';
