    /**
     * Compress image to reduce size
     * @param {string} base64 - Base64 image string
     * @param {number} maxWidth - Maximum width
     * @param {number} quality - JPEG quality (0-1)
     * @returns {Promise<string>} Compressed base64
     */
    async compressImage(base64, maxWidth = 800, quality = 0.7) {
        return new Promise((resolve) => {
            const img = new Image();
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let width = img.width;
                let height = img.height;
                
                if (width > maxWidth) {
                    height = (height * maxWidth) / width;
                    width = maxWidth;
                }
                
                canvas.width = width;
                canvas.height = height;
                
                const ctx = canvas.getContext('2d');
                ctx.drawImage(img, 0, 0, width, height);
                
                const compressed = canvas.toDataURL('image/jpeg', quality);
                resolve(compressed);
            };
            img.src = base64;
        });
    },
    
    async handleIssueImages(event) {
        const files = event.target.files;
        if (!files.length) return;
        
        const previewContainer = document.getElementById('issue-image-preview');
        this.state.current.issueImages = [];
        
        // ✅ FIX: Compress images to prevent QuotaExceededError
        for (const file of Array.from(files)) {
            if (!file.type.match('image.*')) continue;
            
            try {
                const base64 = await new Promise((resolve, reject) => {
                    const reader = new FileReader();
                    reader.onload = (e) => resolve(e.target.result);
                    reader.onerror = reject;
                    reader.readAsDataURL(file);
                });
                
                // Compress image (max 800px width, 70% quality)
                const compressed = await this.compressImage(base64, 800, 0.7);
                
                this.state.current.issueImages.push(compressed);
                
                const thumbnail = document.createElement('div');
                thumbnail.className = 'relative';
                thumbnail.innerHTML = `
                    <img src="${compressed}" alt="Issue Image" class="image-thumbnail">
                `;
                previewContainer.appendChild(thumbnail);
            } catch (error) {
                console.error('Image compression error:', error);
                this.showError('ไม่สามารถประมวลผลรูปภาพได้');
            }
        }
    },
    
    async submitIssue() {
        if(this._issueSaving)return false;
        if (!this.state.current.issueType) {
            this.showError('กรุณาเลือกประเภทปัญหา');
            return;
        }
        
        const original = this.state.current.item;
        if (!original) return false;
        const item=JSON.parse(JSON.stringify(original));
        this._issueSaving=true;
        try {
        
        const description = document.getElementById('issue-description').value;
        
        item.status = STATUS.ISSUE;
        item.issueNote = this.state.current.issueType;
        item.issueDescription = description;
        item.issueImages = [...this.state.current.issueImages];
        item.issueReportedBy = this.state.ui.currentUser;
        item.issueReportedDate = new Date().toLocaleDateString('th-TH');
        item.lastModified = Date.now();
        
        const history={id:this._uid(),date:new Date().toLocaleDateString('en-CA'),time:new Date().toLocaleTimeString('th-TH'),user:this.state.ui.currentUser,item:item.code,qty:item.qty,loc:item.newLoc||item.oldLoc||'',action:'issue',remark:item.issueNote+(description?' · '+description:''),timestamp:Date.now()};
        if(await this.commitWorkflowDocuments([{collection:COLLECTIONS.ITEMS,data:item},{collection:COLLECTIONS.HISTORY,data:history}])!==true){this.showError('แจ้งปัญหาไม่สำเร็จ ข้อมูลที่กรอกยังอยู่ กรุณาลองใหม่');return false;}
        Object.assign(original,item);
        const live=this.state.data.items.find(i=>i.id===item.id);if(live)Object.assign(live,item);
        if(!this.state.data.history.some(h=>h.id===history.id))this.state.data.history.push(history);
        this.saveData();
        
        this.showSuccess('แจ้งปัญหาเรียบร้อย');
        this.closeIssueModal();
        this.closeModal('modal-detail');
        
        this.state.current.issueType = null;
        this.state.current.issueImages = [];
        
        this.refreshCurrentView(); // ✅ Real-time refresh
        return true;
        }finally{this._issueSaving=false;}
    },

    // Reject functions
    adminRejectItem() {
        document.getElementById('modal-reject-item').classList.remove('hidden');
    },
    
    closeRejectItemModal() {
        document.getElementById('modal-reject-item').classList.add('hidden');
    },
    
    toggleRejectOtherReason() {
        const val = document.getElementById('reject-reason').value;
        const otherInp = document.getElementById('reject-reason-other');
        if(val === 'อื่นๆ') {
            otherInp.classList.remove('hidden');
            otherInp.focus();
        } else {
            otherInp.classList.add('hidden');
        }
    },
    
    confirmRejectItem() {
        const item = this.state.current.item;
        if (!item) return;
        
        let reason = document.getElementById('reject-reason').value;
        if (reason === 'อื่นๆ') {
            reason = document.getElementById('reject-reason-other').value;
        }
        
        const note = document.getElementById('reject-note').value;
        
        if (!reason) {
            this.showError('กรุณาระบุสาเหตุการยกเลิก');
            return;
        }
        
        item.status = STATUS.REJECTED;
        item.rejectReason = reason;
        item.rejectNote = note;
        item.rejectedBy = this.state.ui.currentUser;
        item.rejectDate = new Date().toLocaleDateString('th-TH');
        item.lastModified = Date.now();
        
        this.saveToFirebase(COLLECTIONS.ITEMS, item);
        this.logHistory(item, 'Rejected: ' + reason, 'Rejected');
        
        this.showSuccess('ยกเลิกสินค้าเรียบร้อย');
        this.closeRejectItemModal();
        this.closeModal('modal-detail');
        
        this.refreshCurrentView(); // ✅ Real-time refresh
    },

