    /**
     * Add user from input - ✅ Real-time sync to Firebase
     */
    async addUserFromInput() {
        const input = document.getElementById('new-user-input');
        const username = input.value.trim();
        
        if (!username) {
            this.showError('กรุณาใส่ชื่อผู้ใช้');
            return;
        }
        
        if (this.state.data.users.includes(username)) {
            this.showError('ชื่อผู้ใช้นี้มีอยู่แล้ว');
            return;
        }
        
        // เพิ่มใน local state
        this.state.data.users.push(username);
        this.saveData();
        
        // ✅ Sync to Firebase
        await this.syncUsersToFirebase();
        
        // Clear input และ refresh UI
        input.value = '';
        this.renderUsersList();
        this.showSuccess(`เพิ่มผู้ใช้ "${username}" สำเร็จ`);
    },
    
    /**
     * Remove user - ✅ Real-time sync to Firebase
     */
    async removeUser(username) {
        if (!confirm(`ต้องการลบผู้ใช้ "${username}" ใช่หรือไม่?`)) return;
        
        // ลบจาก local state
        this.state.data.users = this.state.data.users.filter(u => u !== username);
        this.saveData();
        
        // ✅ Sync to Firebase
        await this.syncUsersToFirebase();
        
        // Refresh UI
        this.renderUsersList();
        this.showSuccess(`ลบผู้ใช้ "${username}" สำเร็จ`);
    },
    
    /**
     * Add admin from input - ✅ Real-time sync to Firebase
     */
