    renderAdminRecycle() {
        const container = document.getElementById('admin-recycle-container');
        const list = this.state.data.items.filter(i => i.status === STATUS.DELETED);

        if (list.length === 0) {
            container.innerHTML = `<div class="text-center text-slate-400 py-10">ถังขยะว่างเปล่า</div>`;
            return;
        }

        container.innerHTML = list.map(item => `
            <div class="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col gap-2">
                <div class="flex justify-between items-start">
                    <div class="font-bold text-lg text-slate-800">${this.copyInline(item.code, 'Item')}</div>
                    <span class="bg-slate-100 text-slate-600 text-xs font-bold px-2 py-1 rounded">Deleted</span>
                </div>
                <div class="text-sm text-slate-600 truncate">${item.desc}</div>
                <div class="text-xs text-slate-400 mt-1">Original Status: <span class="font-bold text-slate-700">${item.originalStatus || '-'}</span></div>
                <div class="text-xs text-slate-500 flex flex-wrap gap-2">
                    <span>LOC เดิม: ${this.copyInline(item.oldLoc || '-', 'LOC เดิม')}</span>
                    <span>LOC ใหม่: ${this.copyInline(item.newLoc || '-', 'LOC ใหม่')}</span>
                </div>
                <div class="flex gap-2 mt-2">
                    <button onclick="window.app.restoreItem(${item.id})" class="flex-1 py-2 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg text-sm font-bold hover:bg-emerald-100">
                        <i class="ph ph-arrow-u-up-left"></i> Restore
                    </button>
                    <button onclick="window.app.permanentDeleteItem(${item.id})" class="px-3 py-2 bg-red-50 text-red-600 border border-red-200 rounded-lg text-sm font-bold hover:bg-red-100">
                        <i class="ph ph-x"></i> Del Forever
                    </button>
                </div>
            </div>
        `).join('');
    },

    async restoreItem(id) {
        if(!confirm('คืนค่ารายการนี้?')) return;
        const item = this.state.data.items.find(i => i.id === id);
        if(item) {
            item.status = item.originalStatus || STATUS.PENDING;
            item.lastModified = Date.now();
            this.saveToFirebase(COLLECTIONS.ITEMS, item);
            
            this.state.data.items = this.state.data.items.filter(i => i.id !== id);
            this.saveData();
            this.renderAdminRecycle();
            this.showSuccess('คืนค่ารายการสำเร็จ');
        }
    },

    async permanentDeleteItem(id) {
        if(!confirm('ลบข้อมูลถาวร? จะไม่สามารถกู้คืนได้')) return;
        const item = this.state.data.items.find(i => i.id === id);
        if(item) {
            try {
                await deleteDoc(doc(db, COLLECTIONS.ITEMS, id.toString()));
                this.state.data.items = this.state.data.items.filter(i => i.id !== id);
                this.saveData();
                this.renderAdminRecycle();
                this.showSuccess('ลบถาวรเรียบร้อย');
            } catch(e) {
                this.showError('เกิดข้อผิดพลาดในการลบ');
            }
        }
    },

    // Import functions — รองรับ PLAS 8 คอลัมน์เดิมและตาราง AX แบบ Copy/Paste
