    // Rejected filter
    filterRejected(period) {
        this.state.filters.rejectedFilter = period;
        this.renderAdminRejected();
    },

    renderAdminRejected() {
        const container = document.getElementById('admin-rejected-container');
        let list = [...this.state.data.items].filter(i => i.status === STATUS.REJECTED);
        
        const now = new Date();
        if(this.state.filters.rejectedFilter === 'today') {
            const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
            list = list.filter(i => {
                if (!i.rejectDate) return false;
                const rejectDate = new Date(i.rejectDate);
                return rejectDate >= today;
            });
        } else if(this.state.filters.rejectedFilter === 'week') {
            const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
            list = list.filter(i => {
                if (!i.rejectDate) return false;
                const rejectDate = new Date(i.rejectDate);
                return rejectDate >= weekAgo;
            });
        }
        
        list.sort((a,b) => {
            if (!a.rejectDate) return 1;
            if (!b.rejectDate) return -1;
            return new Date(b.rejectDate) - new Date(a.rejectDate);
        });
        
        if(!list.length) { 
            container.innerHTML = `<div class="text-center text-slate-400 py-10">ไม่มีสินค้าที่ถูกยกเลิก</div>`; 
            return; 
        }

        this.renderSmartList('admin-rejected-container', list, { adminCopy: true });
    },

    // Item X-Ray modal
    closeItemXRay() {
        document.getElementById('modal-item-xray').classList.add('hidden');
    },

    // Reports
    switchReportTab(tab) {
        this.state.current.reportTab = tab;
        var repTabs = ['receiving', 'topup', 'move'];
        var tabColors = {receiving: 'blue', topup: 'teal', move: 'amber'};
        for (var ri = 0; ri < repTabs.length; ri++) {
            var rt = repTabs[ri];
            var repBtn = document.getElementById('rep-tab-' + rt);
            if (!repBtn) continue;
            if(rt === tab) {
                repBtn.className = "flex-1 py-2.5 font-bold text-sm rounded-xl bg-" + tabColors[rt] + "-50 text-" + tabColors[rt] + "-700 border-2 border-" + tabColors[rt] + "-200";
            } else {
                repBtn.className = "flex-1 py-2.5 font-bold text-sm rounded-xl text-slate-500 bg-white border-2 border-slate-200 hover:bg-slate-50";
            }
        }
        this.loadReportData();
    },

    handleReportDateChange() {
        const val = document.getElementById('report-date-picker').value;
        this.state.current.reportDate = val;
        this.loadReportData();
    },

    async loadReportData() {
        const container = document.getElementById('report-table-container');
        const loading = document.getElementById('report-loading');
        
        loading.classList.remove('hidden');
        container.classList.add('hidden');
        container.innerHTML = '';

        try {
            const todayStr = new Date().toISOString().slice(0,10);
            const isToday = this.state.current.reportDate === todayStr;
            
            let data = [];

            const q = query(collection(db, COLLECTIONS.ARCHIVES), where('archiveDate', '==', this.state.current.reportDate));
            const snapshot = await getDocs(q);
            snapshot.forEach(doc => {
                const d = doc.data();
                if (this.state.current.reportTab === 'receiving' && d.collection === COLLECTIONS.ITEMS) data.push(d);
                if (this.state.current.reportTab === 'topup' && d.collection === COLLECTIONS.JOBS) data.push(d);
                if (this.state.current.reportTab === 'move' && d.collection === COLLECTIONS.MOVES) data.push(d);
            });

            if (isToday) {
                let activeData = [];
                if (this.state.current.reportTab === 'receiving') activeData = this.state.data.items;
                if (this.state.current.reportTab === 'topup') activeData = this.state.data.replenishmentJobs;
                if (this.state.current.reportTab === 'move') activeData = this.state.data.moveJobs;
                data = [...data, ...activeData];
            }

            const uniqueMap = new Map();
            data.forEach(item => {
                const key = item.originalId || item.id;
                if (!uniqueMap.has(key)) {
                    uniqueMap.set(key, item);
                }
            });
            
            const mergedData = Array.from(uniqueMap.values());
            mergedData.sort((a, b) => (b.lastModified || b.id || 0) - (a.lastModified || a.id || 0));

            this.state.current.reportData = mergedData;
            this.renderReportTable();

        } catch (e) {
            console.error(e);
            this.showError('Error loading report data');
        } finally {
            loading.classList.add('hidden');
            container.classList.remove('hidden');
        }
    },

