    /**
     * ✅ NEW: Filter report table by search term
     * @param {string} searchTerm - Search query
     */
    filterReportTable(searchTerm) {
        const tbody = document.querySelector('#report-table-container tbody');
        if (!tbody) return;

        const rows = tbody.querySelectorAll('tr');
        const term = searchTerm.toLowerCase().trim();

        if (!term) {
            // Show all rows if search is empty
            rows.forEach(row => row.style.display = '');
            return;
        }

        let visibleCount = 0;
        rows.forEach(row => {
            const text = row.textContent.toLowerCase();
            if (text.includes(term)) {
                row.style.display = '';
                visibleCount++;
            } else {
                row.style.display = 'none';
            }
        });

        // Show message if no results
        const container = document.getElementById('report-table-container');
        let noResultMsg = container.querySelector('.no-search-results');
        
        if (visibleCount === 0 && term) {
            if (!noResultMsg) {
                noResultMsg = document.createElement('div');
                noResultMsg.className = 'no-search-results text-center text-slate-400 py-8';
                noResultMsg.innerHTML = `
                    <i class="ph ph-magnifying-glass text-4xl mb-2 opacity-50"></i>
                    <p class="font-bold">ไม่พบรายการที่ค้นหา</p>
                    <p class="text-sm">ลองใช้คำค้นหาอื่น</p>
                `;
                container.appendChild(noResultMsg);
            }
            noResultMsg.style.display = 'block';
        } else if (noResultMsg) {
            noResultMsg.style.display = 'none';
        }
    },

