    /* ─── Drag-resize the report table section ──────────── */
    _initReportResizeHandle() {
        if (this.__reportResizeInited) return;
        this.__reportResizeInited = true;
        const handle = document.getElementById('report-resize-handle');
        const tableWrap = document.getElementById('report-table-wrap');
        const container = document.getElementById('admin-view-reports');
        if (!handle || !tableWrap || !container) return;
        let startY = 0, startH = 0, dragging = false;
        handle.addEventListener('mousedown', (e) => {
            if (e.target.tagName === 'BUTTON') return; // don't drag when clicking button
            dragging = true;
            startY = e.clientY;
            startH = tableWrap.getBoundingClientRect().height;
            document.body.style.cursor = 'ns-resize';
            document.body.style.userSelect = 'none';
        });
        document.addEventListener('mousemove', (e) => {
            if (!dragging) return;
            const delta = e.clientY - startY;
            const newH = Math.max(150, startH - delta);
            tableWrap.style.flexBasis = newH + 'px';
            tableWrap.style.flexGrow = '0';
            tableWrap.style.flexShrink = '0';
        });
        document.addEventListener('mouseup', () => {
            if (dragging) {
                dragging = false;
                document.body.style.cursor = '';
                document.body.style.userSelect = '';
            }
        });
        // Touch support
        handle.addEventListener('touchstart', (e) => {
            if (e.target.tagName === 'BUTTON') return;
            dragging = true;
            startY = e.touches[0].clientY;
            startH = tableWrap.getBoundingClientRect().height;
        }, { passive: true });
        document.addEventListener('touchmove', (e) => {
            if (!dragging) return;
            const delta = e.touches[0].clientY - startY;
            const newH = Math.max(150, startH - delta);
            tableWrap.style.flexBasis = newH + 'px';
            tableWrap.style.flexGrow = '0';
            tableWrap.style.flexShrink = '0';
        }, { passive: true });
        document.addEventListener('touchend', () => { dragging = false; });
    },

    exportMonitorCSV() {
        const data = this.state.current.reportData || [];
        if (data.length === 0) { this.showError('ไม่มีข้อมูล'); return; }
        const tab = this.state.current.reportTab;
        let csv = '';
        if (tab === 'receiving') {
            csv = 'PO,Code,Comp,Description,Qty,Batch,OldLoc,NewLoc,Writer,Receiver,Status\n';
            data.forEach(i => { csv += [i.po,i.code,i.comp,'"'+(i.desc||'')+'"',i.qty,i.batch,i.oldLoc,i.newLoc,i.locWrittenBy,i.importedBy,i.status].join(',') + '\n'; });
        } else if (tab === 'topup') {
            csv = 'DocNo,Item,Qty,From,To,CreatedBy,AssignedTo,Status\n';
            data.forEach(j => { csv += [j.docNo,j.item,j.qty,j.fromLoc,j.toLoc,j.createdBy,j.assignedTo,j.status].join(',') + '\n'; });
        } else {
            csv = 'Item,Qty,From,To,By,Time,Status\n';
            data.forEach(m => { csv += [m.item,m.qty,m.oldLoc,m.newLoc,m.createdBy,m.timestamp,m.status].join(',') + '\n'; });
        }
        const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
        const a = document.createElement('a');
        a.href = URL.createObjectURL(blob);
        a.download = 'WMS-' + this.state.current.reportDate.replace(/-/g,'') + '-' + tab + '.csv';
        a.click();
        this.showSuccess('Export CSV สำเร็จ');
    },

